        cout << "Poor Inna and pony!\n";
        return 0;
    }

    const long long INF = numeric_limits<long long>::max();
    long long answer = INF;
    long long rows[2] = {1, n};
    long long columns[2] = {1, m};

    for (long long row : rows) {
        for (long long column : columns) {
            long long dx = row > i ? row - i : i - row;
            long long dy = column > j ? column - j : j - column;

            if (dx % a != 0 || dy % b != 0)
                continue;

            long long x = dx / a;
            long long y = dy / b;

            if (x % 2 == y % 2)
                answer = min(answer, max(x, y));
        }
    }

    if (answer == INF)
        cout << "Poor Inna and pony!\n";
    else
        cout << answer << '\n';

    return 0;
}

